-- Full cached-document research, per-model quotas and durable task checkpoints.
begin;
create table if not exists paperlab.deep_runtime(singleton boolean primary key default true check(singleton),enabled boolean not null default false,token uuid,lease_until timestamptz,job_id text,last_attempt timestamptz,last_success timestamptz,status text not null default 'not_enabled',month date,estimated_bytes bigint not null default 0);
insert into paperlab.deep_runtime(singleton)values(true)on conflict do nothing;
create table if not exists paperlab.deep_models(model text primary key,daily_limit int not null,rpm int not null,tpm int not null,day date,used int not null default 0,minute timestamptz,minute_used int not null default 0,minute_tokens int not null default 0,retry_after timestamptz,last_status text,check(model in('gemini-3.5-flash-lite','gemini-3.8-flash')),check(daily_limit between 1 and 500));
insert into paperlab.deep_models(model,daily_limit,rpm,tpm)values('gemini-3.5-flash-lite',500,15,250000),('gemini-3.8-flash',20,5,250000)on conflict do nothing;
create table if not exists paperlab.deep_companies(symbol text primary key,priority int not null default 10,generation text,coverage jsonb not null default '{}',report jsonb,audit jsonb,status text not null default 'waiting_documents',last_completed timestamptz,next_discovery timestamptz not null default now(),gaps jsonb not null default '[]');
create table if not exists paperlab.deep_documents(id text primary key,symbol text not null references paperlab.deep_companies,url text not null,sha256 text not null,body_sha256 text not null,body text not null check(octet_length(body)<=8000000),kind text not null,role text not null check(role in('annual','interim','material','other')),known_at timestamptz not null,filed_at date,scope text not null,complete_extraction boolean not null,active boolean not null default true,characters int not null,chunks int not null,created_at timestamptz not null default now(),unique(symbol,url,sha256));
create table if not exists paperlab.deep_jobs(id text primary key,symbol text not null references paperlab.deep_companies,stage text not null check(stage in('discover','extract','pillar','audit')),model text references paperlab.deep_models,doc_id text references paperlab.deep_documents,chunk_no int,pillar text,generation text,priority int not null default 10,status text not null default 'queued'check(status in('queued','leased','retry','completed','blocked','superseded')),available_at timestamptz not null default now(),token uuid,lease_until timestamptz,attempts int not null default 0,result jsonb check(octet_length(result::text)<=40000),created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists deep_jobs_ready on paperlab.deep_jobs(status,available_at,priority desc);
create index if not exists deep_jobs_document on paperlab.deep_jobs(doc_id,stage,status);
create table if not exists paperlab.deep_events(id bigserial primary key,at timestamptz not null default now(),symbol text,event text not null,record jsonb not null check(octet_length(record::text)<=4000));
do $$declare t text;begin foreach t in array array['deep_runtime','deep_models','deep_companies','deep_documents','deep_jobs','deep_events']loop execute format('alter table paperlab.%I enable row level security',t);execute format('revoke all on paperlab.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create or replace function paperlab.deep_add_document(x jsonb)returns text language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare i text;count_chunks int;n int;s text:=x->>'symbol';begin
 if not exists(select 1 from paperlab.company_research where symbol=s)or coalesce(x->>'url','')not like'https://%'or coalesce(x->>'sha256','')!~'^[a-f0-9]{64}$'or x->>'role'not in('annual','interim','material','other')or length(coalesce(x->>'text',''))not between 300 and 2000000 or octet_length(x->>'text')>8000000 or((x->>'known_at')::timestamptz<=now())is not true or x->>'complete_extraction'not in('true','false')then raise exception 'Known bounded public document required';end if;
 if pg_database_size(current_database())>97000000 then raise exception 'Document cache database budget';end if;
 insert into paperlab.deep_companies(symbol,priority)values(s,coalesce((select priority from paperlab.research_queue where symbol=s),10))on conflict do nothing;
 i:=encode(sha256(convert_to(s||'|'||(x->>'url')||'|'||(x->>'sha256'),'UTF8')),'hex');
 if exists(select 1 from paperlab.deep_documents where id=i)then update paperlab.deep_documents set body=x->>'text'where id=i and body=''and body_sha256=encode(sha256(convert_to(x->>'text','UTF8')),'hex');return i;end if;
 count_chunks:=ceil(length(x->>'text')/7000.0)::int;
 insert into paperlab.deep_documents(id,symbol,url,sha256,body_sha256,body,kind,role,known_at,filed_at,scope,complete_extraction,characters,chunks)values(i,s,x->>'url',x->>'sha256',encode(sha256(convert_to(x->>'text','UTF8')),'hex'),x->>'text',x->>'kind',x->>'role',(x->>'known_at')::timestamptz,nullif(x->>'filed_at','')::date,x->>'scope',(x->>'complete_extraction')::boolean,length(x->>'text'),count_chunks);
 -- Same URL content editions supersede older editions; annual/quarter forms keep one latest edition each.
 update paperlab.deep_documents set active=false where symbol=s and id<>i and(url=x->>'url'or(kind=x->>'kind'and kind in('10-K','10-Q','20-F')and coalesce(filed_at,known_at::date)<=coalesce(nullif(x->>'filed_at','')::date,(x->>'known_at')::timestamptz::date)));
 update paperlab.deep_jobs j set status='superseded'from paperlab.deep_documents d where j.doc_id=d.id and d.symbol=s and not d.active and j.status in('queued','retry');
 for n in 0..count_chunks-1 loop insert into paperlab.deep_jobs(id,symbol,stage,model,doc_id,chunk_no,priority)values(i||':chunk:'||n,s,'extract','gemini-3.5-flash-lite',i,n,coalesce((select priority from paperlab.deep_companies where symbol=s),10))on conflict do nothing;end loop;
 update paperlab.deep_companies set status='reading_documents',generation=null where symbol=s;
 return i;
end$$;
revoke all on function paperlab.deep_add_document(jsonb)from public,anon,authenticated,service_role;
create or replace function public.paper_deep_seed(p_owner uuid,p_rows jsonb)returns int language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare x jsonb;n int:=0;begin
 if p_owner is distinct from(select owner_id from paperlab.settings where singleton)then raise exception 'Owner required';end if;
 if jsonb_typeof(p_rows)is distinct from'array'or jsonb_array_length(p_rows)>5 then raise exception 'Small seed batch required';end if;
 for x in select value from jsonb_array_elements(p_rows)loop perform paperlab.deep_add_document(x);n:=n+1;end loop;return n;
end$$;
create or replace function paperlab.deep_plan()returns void language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare c paperlab.deep_companies;g text;p text;v_coverage jsonb;annual boolean;interim boolean;begin
 insert into paperlab.deep_companies(symbol,priority)select r.symbol,coalesce(q.priority,10)from paperlab.company_research r left join paperlab.research_queue q using(symbol)on conflict(symbol)do update set priority=excluded.priority;
 for c in select *from paperlab.deep_companies loop
  if c.next_discovery<=now()and not exists(select 1 from paperlab.deep_jobs where symbol=c.symbol and stage='discover'and status in('queued','retry','leased'))then insert into paperlab.deep_jobs(id,symbol,stage,priority)values(c.symbol||':discover:'||to_char(now()at time zone'UTC','YYYYMMDDHH24MI'),c.symbol,'discover',c.priority-20)on conflict do nothing;end if;
  select encode(sha256(convert_to(coalesce(string_agg(id,'|'order by id),''),'UTF8')),'hex'),coalesce(bool_or(role='annual'and complete_extraction),false),coalesce(bool_or(role='interim'and complete_extraction and kind in('10-Q','6-K','official_report')),false)into g,annual,interim from paperlab.deep_documents where symbol=c.symbol and active and role<>'other';
  v_coverage:=jsonb_build_object('annual_present',annual,'interim_present',interim,'active_documents',(select count(*)from paperlab.deep_documents where symbol=c.symbol and active and role<>'other'),'chunks_total',(select count(*)from paperlab.deep_jobs j join paperlab.deep_documents d on d.id=j.doc_id where j.symbol=c.symbol and j.stage='extract'and d.active and d.role<>'other'),'chunks_completed',(select count(*)from paperlab.deep_jobs j join paperlab.deep_documents d on d.id=j.doc_id where j.symbol=c.symbol and j.stage='extract'and j.status='completed'and d.active and d.role<>'other'));
  update paperlab.deep_companies set generation=g,coverage=v_coverage where symbol=c.symbol;
  if(v_coverage->>'chunks_total')::int>0 and v_coverage->>'chunks_total'=v_coverage->>'chunks_completed'and not exists(select 1 from paperlab.deep_jobs where symbol=c.symbol and stage='extract'and status in('blocked','leased')and doc_id in(select id from paperlab.deep_documents where symbol=c.symbol and active))then
   foreach p in array array['financial_position','cash_earnings','competitive_position','management','valuation','risks']loop insert into paperlab.deep_jobs(id,symbol,stage,model,pillar,generation,priority)values(c.symbol||':'||g||':'||p,c.symbol,'pillar','gemini-3.5-flash-lite',p,g,c.priority+20)on conflict do nothing;end loop;
   if(select count(*)from paperlab.deep_jobs where symbol=c.symbol and generation=g and stage='pillar'and status='completed')=6 then insert into paperlab.deep_jobs(id,symbol,stage,model,generation,priority)values(c.symbol||':'||g||':audit',c.symbol,'audit','gemini-3.8-flash',g,c.priority+30)on conflict do nothing;end if;
  end if;
 end loop;
end$$;
revoke all on function paperlab.deep_plan()from public,anon,authenticated,service_role;
create or replace function public.paper_deep_enable(p_owner uuid)returns boolean language plpgsql security definer set search_path=pg_catalog,pg_temp as $$begin
 if p_owner is distinct from(select owner_id from paperlab.settings where singleton)then raise exception 'Owner required';end if;
 if not exists(select 1 from paperlab.gemini_runtime where free_tier_confirmed_at is not null and quota_evidence->'models'->'gemini-3.5-flash-lite'->>'rpd'='500'and quota_evidence->'models'->'gemini-3.8-flash'->>'rpd'='20')then raise exception 'Confirmed free project and per-model quota evidence required';end if;
 update paperlab.deep_runtime set enabled=true,status='enabled_waiting'where singleton;return true;
end$$;
create or replace function public.paper_deep_claim()returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$
declare r paperlab.deep_runtime;j paperlab.deep_jobs;b paperlab.deep_models;doc paperlab.deep_documents;d date:=(now()at time zone'America/Los_Angeles')::date;m date:=date_trunc('month',now()at time zone'UTC')::date;mi timestamptz:=date_trunc('minute',now());t uuid;payload jsonb;source text;charge bigint;token_bound int;begin
 select *into r from paperlab.deep_runtime where singleton for update;if not r.enabled or r.lease_until>now()then return null;end if;
 update paperlab.deep_jobs set status='retry',available_at=now()+interval'1 minute',token=null,lease_until=null where status='leased'and lease_until<=now();
 if r.month is distinct from m then r.estimated_bytes:=0;end if;
 update paperlab.deep_models set day=d,used=0 where day is distinct from d;
 update paperlab.deep_models set minute=mi,minute_used=0,minute_tokens=0 where minute is distinct from mi;
 perform paperlab.deep_plan();
 select x.*into j from paperlab.deep_jobs x left join paperlab.deep_models bm on bm.model=x.model left join paperlab.deep_models hm on hm.model='gemini-3.8-flash' where x.status in('queued','retry')and x.available_at<=now()and(x.model is null or(bm.used<bm.daily_limit and bm.minute_used<bm.rpm and bm.minute_tokens+100000<=bm.tpm and coalesce(bm.retry_after,'-infinity')<=now())or(x.stage='extract'and x.model='gemini-3.5-flash-lite'and(bm.used>=bm.daily_limit or bm.retry_after>now())and hm.used<hm.daily_limit and hm.minute_used<hm.rpm and hm.minute_tokens+100000<=hm.tpm and coalesce(hm.retry_after,'-infinity')<=now()))and(x.generation is null or x.generation=(select generation from paperlab.deep_companies where symbol=x.symbol))order by x.priority desc,case x.stage when 'audit'then 0 when 'pillar'then 1 when 'extract'then 2 else 3 end,x.created_at,x.doc_id,x.chunk_no limit 1 for update of x;
 if not found then update paperlab.deep_runtime set status='waiting_work_or_quota'where singleton;return null;end if;
 if j.model='gemini-3.5-flash-lite'and j.stage='extract'and exists(select 1 from paperlab.deep_models where model=j.model and(used>=daily_limit or retry_after>now()))then j.model:='gemini-3.8-flash';update paperlab.deep_jobs set model=j.model where id=j.id;end if;
 if j.stage='extract'then
  select *into doc from paperlab.deep_documents where id=j.doc_id and active;
  if not found then update paperlab.deep_jobs set status='superseded'where id=j.id;return null;end if;
  if doc.body=''then update paperlab.deep_runtime set status='cache_restore_required'where singleton;return null;end if;
  source:=substring(doc.body from j.chunk_no*7000+1 for 7000);
  payload:=jsonb_build_object('symbol',j.symbol,'source',jsonb_build_object('id',doc.id,'url',doc.url,'sha256',doc.sha256,'body_sha256',doc.body_sha256,'known_at',doc.known_at,'role',doc.role,'scope',doc.scope,'complete_extraction',doc.complete_extraction,'chunk',j.chunk_no,'chunks',doc.chunks,'offset',j.chunk_no*7000,'header',left(doc.body,700),'text',source));
 elsif j.stage='discover'then
  select jsonb_build_object('symbol',j.symbol,'sources',coalesce((select record->'sources'from paperlab.scoped_research where symbol=j.symbol order by recorded_at desc limit 1),'[]'::jsonb)||coalesce(c.record->'sources','[]'::jsonb),'known_urls',(select coalesce(jsonb_agg(url),'[]')from paperlab.deep_documents where symbol=j.symbol),'cik',c.record->>'cik')into payload from paperlab.company_research c where symbol=j.symbol;
 else
  payload:=jsonb_build_object('symbol',j.symbol,'pillar',j.pillar,'fact_selection',jsonb_build_object('context_limit',case when j.stage='audit'then 18 else 60 end,'total_extracted_facts',(select coalesce(sum(jsonb_array_length(z.result->'claims')),0)from paperlab.deep_jobs z join paperlab.deep_documents sd on sd.id=z.doc_id where z.symbol=j.symbol and z.stage='extract'and z.status='completed'and sd.active),'scope','Topic-ranked selection of extracted facts; original full texts remain cached. Do not infer exhaustive audit.'),'coverage',(select coverage from paperlab.deep_companies where symbol=j.symbol),'facts',(select coalesce(jsonb_agg(v),'[]')from(select jsonb_build_object('id',z.id||':'||(f.ordinality-1),'finding',f.value->>'finding','topic',f.value->>'topic','quote',f.value->>'quote','period',f.value->>'period','basis',f.value->>'basis','source_id',z.doc_id,'url',s.url,'context',substring(s.body from greatest(1,z.chunk_no*7000+strpos(substring(s.body from z.chunk_no*7000+1 for 7000),f.value->>'quote')-350)for 500))v from paperlab.deep_jobs z join paperlab.deep_documents s on s.id=z.doc_id cross join lateral jsonb_array_elements(z.result->'claims')with ordinality f(value,ordinality)where z.symbol=j.symbol and z.stage='extract'and z.status='completed'and s.active order by case when f.value->>'topic'=j.pillar then 0 when j.pillar='valuation'and f.value->>'topic'='cash_earnings'then 1 else 2 end,s.known_at desc,z.chunk_no limit case when j.stage='audit'then 18 else 60 end)a),'pillars',(select coalesce(jsonb_agg(jsonb_build_object('pillar',pillar,'result',result)),'[]')from paperlab.deep_jobs where symbol=j.symbol and generation=j.generation and stage='pillar'and status='completed'),'peer_context',(select coalesce(jsonb_agg(v),'[]')from(select jsonb_build_object('symbol',pc.symbol,'source_url',pc.record->>'source_url','known_at',pc.record->>'secondary_checked_at','values',(select jsonb_object_agg(key,value)from jsonb_each(pc.record->'observation'->'values')where key in('annualTotalRevenue','annualNetIncome','annualOperatingCashFlow','annualFreeCashFlow','annualTotalDebt','annualCashAndCashEquivalents')),'comparison_scope','same catalogue sector; economic comparability requires review')v from paperlab.company_coverage pc join(select value c from paperlab.company_coverage_runtime cr,jsonb_array_elements(cr.catalogue))cat on cat.c->>'symbol'=pc.symbol where pc.symbol<>j.symbol and cat.c->>'sector'=(select value->>'sector'from paperlab.company_coverage_runtime cr,jsonb_array_elements(cr.catalogue)where value->>'symbol'=j.symbol)order by pc.symbol limit 2)peers),'financial_context',(select jsonb_build_object('source_url',record->>'source_url','source_hash',record->>'source_hash','known_at',record->>'secondary_checked_at','quote',(select jsonb_build_object('price',state->'last_observation'->j.symbol->'price','bid',state->'last_observation'->j.symbol->'bid','ask',state->'last_observation'->j.symbol->'ask','currency',state->'last_observation'->j.symbol->>'currency','time',state->'last_observation'->j.symbol->>'time')from paperlab.portfolio limit 1),'values',record->'observation'->'values','independently_verified',false)from paperlab.company_coverage where symbol=j.symbol),'consensus',(select record from paperlab.analyst_consensus where symbol=j.symbol));
 end if;
 charge:=case when j.stage='discover'then 500000 else 2*octet_length(payload::text)+25000 end;
 insert into paperlab.free_usage(month)values(m)on conflict do nothing;perform 1 from paperlab.free_usage where month=m for update;
 if r.estimated_bytes+charge>1200000000 or(select estimated_worker_egress_bytes+charge from paperlab.free_usage where month=m)>paperlab.traffic_limit('soft')or pg_database_size(current_database())>99000000 then update paperlab.deep_runtime set status='storage_or_transfer_budget_guard'where singleton;return null;end if;
 if j.model is not null then
  token_bound:=octet_length(payload::text)+16000;
  if token_bound>100000 then update paperlab.deep_jobs set status='blocked',result=jsonb_build_object('status','invalid_response','reason','bounded_input_exceeded')where id=j.id;return null;end if;
  select *into b from paperlab.deep_models where model=j.model for update;
  update paperlab.deep_models set used=used+1,minute_used=minute_used+1,minute_tokens=minute_tokens+token_bound,last_status='reserved'where model=j.model;
 end if;
 t:=gen_random_uuid();update paperlab.deep_jobs set status='leased',token=t,lease_until=now()+interval'240 seconds',attempts=attempts+1 where id=j.id;
 update paperlab.deep_runtime set token=t,lease_until=now()+interval'240 seconds',job_id=j.id,last_attempt=now(),status='processing_'||j.stage,month=m,estimated_bytes=r.estimated_bytes+charge where singleton;
 update paperlab.free_usage set estimated_worker_egress_bytes=estimated_worker_egress_bytes+charge where month=m;
 return jsonb_build_object('token',t,'job',jsonb_build_object('id',j.id,'symbol',j.symbol,'stage',j.stage,'model',j.model,'pillar',j.pillar),'input',payload);
end$$;
create or replace function public.paper_deep_reserve_transfer(p_token uuid,p_bytes int)returns boolean language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare r paperlab.deep_runtime;m date:=date_trunc('month',now()at time zone'UTC')::date;begin
 select *into r from paperlab.deep_runtime where singleton and token=p_token and lease_until>now()for update;
 if not found or p_bytes not between 1 and 22000000 then raise exception 'Active bounded source request required';end if;
 insert into paperlab.free_usage(month)values(m)on conflict do nothing;perform 1 from paperlab.free_usage where month=m for update;
 if r.estimated_bytes+p_bytes>1200000000 or(select estimated_worker_egress_bytes+p_bytes from paperlab.free_usage where month=m)>paperlab.traffic_limit('soft')then raise exception 'Source transfer budget';end if;
 update paperlab.deep_runtime set estimated_bytes=estimated_bytes+p_bytes where singleton;update paperlab.free_usage set estimated_worker_egress_bytes=estimated_worker_egress_bytes+p_bytes where month=m;return true;
end$$;
create or replace function public.paper_deep_ingest(p_token uuid,p_rows jsonb,p_gaps jsonb default '[]')returns int language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare j paperlab.deep_jobs;x jsonb;n int:=0;begin
 select *into j from paperlab.deep_jobs where token=p_token and status='leased'and lease_until>now()and stage='discover'for update;if not found then raise exception 'Active discovery required';end if;
 if jsonb_typeof(p_rows)is distinct from'array'or jsonb_array_length(p_rows)>3 or octet_length(p_gaps::text)>4000 then raise exception 'Bounded source ingestion required';end if;
 for x in select value from jsonb_array_elements(p_rows)loop if x->>'symbol'is distinct from j.symbol then raise exception 'Wrong issuer';end if;perform paperlab.deep_add_document(x);n:=n+1;end loop;
 update paperlab.deep_companies set gaps=p_gaps,next_discovery=now()+case when exists(select 1 from paperlab.earnings_cycles where symbol=j.symbol and release_at between now()-interval'7 days'and now()+interval'21 days')then interval'1 day'else interval'7 days'end where symbol=j.symbol;
 return n;
end$$;
create or replace function public.paper_deep_commit(p_token uuid,p_result jsonb)returns boolean language plpgsql security definer set search_path=pg_catalog,pg_temp as $$
declare j paperlab.deep_jobs;b paperlab.deep_models;doc paperlab.deep_documents;source text;x jsonb;h text;retry timestamptz;success boolean;full_report boolean;source_id text;fact_index int;begin
 select *into j from paperlab.deep_jobs where token=p_token and status='leased'and lease_until>now()for update;if not found then return false;end if;
 if octet_length(p_result::text)>40000 or p_result->>'trade_approval'is distinct from'false'or p_result->>'independently_verified'is distinct from'false'or p_result->>'status'not in('completed','rate_limited','provider_unavailable','invalid_response','source_unavailable','blocked_source')then raise exception 'Bounded research-only result required';end if;
 success:=p_result->>'status'='completed';
 if success and j.stage='extract'then
  select *into doc from paperlab.deep_documents where id=j.doc_id;source:=substring(doc.body from j.chunk_no*7000+1 for 7000);
  if jsonb_typeof(p_result->'claims')is distinct from'array'or jsonb_array_length(p_result->'claims')>8 or(jsonb_array_length(p_result->'claims')=0 and p_result->>'no_material_information'is distinct from'true')then raise exception 'Facts or explicit empty passage required';end if;
  for x in select value from jsonb_array_elements(p_result->'claims')loop if coalesce(x->>'topic','')not in('financial_position','cash_earnings','competitive_position','management','valuation','risks','material_events','expectations')or length(coalesce(x->>'finding',''))not between 20 and 1000 or length(coalesce(x->>'quote',''))not between 10 and 220 or strpos(source,x->>'quote')=0 then raise exception 'Exact passage evidence required';end if;end loop;
 elsif success and j.stage='pillar'then
  if p_result->>'pillar'is distinct from j.pillar or length(coalesce(p_result->>'assessment',''))not between 60 and 8000 or jsonb_typeof(p_result->'evidence_ids')is distinct from'array'or jsonb_array_length(p_result->'evidence_ids')>30 or jsonb_typeof(p_result->'limitations')is distinct from'array'or p_result->>'requires_more_data'not in('true','false')or(p_result->>'requires_more_data'='false'and jsonb_array_length(p_result->'evidence_ids')=0)then raise exception 'Sourced pillar required';end if;
  for h in select jsonb_array_elements_text(p_result->'evidence_ids')loop
   if h in('secondary_financials','valuation_scenarios','peer_context')then continue;end if;
   source_id:=regexp_replace(h,':[0-9]+$','');fact_index:=substring(h from':([0-9]+)$')::int;
   if fact_index is null or not exists(select 1 from paperlab.deep_jobs where id=source_id and symbol=j.symbol and stage='extract'and status='completed'and result->'claims'->fact_index is not null)then raise exception 'Unknown fact citation';end if;
  end loop;
 elsif success and j.stage='audit'then
  if jsonb_typeof(p_result->'checks')is distinct from'array'or jsonb_array_length(p_result->'checks')<>6 or(select count(distinct av.value->>'pillar')from jsonb_array_elements(p_result->'checks')av(value))<>6 or length(coalesce(p_result->>'summary',''))not between 80 and 8000 then raise exception 'Six-pillar final audit required';end if;
  for x in select value from jsonb_array_elements(p_result->'checks')loop if x->>'pillar'not in('financial_position','cash_earnings','competitive_position','management','valuation','risks')or x->>'supported'not in('true','false')then raise exception 'Invalid audit check';end if;end loop;
 end if;
 if success then
  update paperlab.deep_jobs set status='completed',result=p_result,completed_at=now(),token=null,lease_until=null where id=j.id;
  if j.stage='audit'then
   full_report:=coalesce(((select coverage->>'annual_present'from paperlab.deep_companies where symbol=j.symbol)::boolean),false)and coalesce(((select coverage->>'interim_present'from paperlab.deep_companies where symbol=j.symbol)::boolean),false)and not exists(select 1 from jsonb_array_elements(p_result->'checks')av(value)where av.value->>'supported'is distinct from'true')and not exists(select 1 from paperlab.deep_jobs where symbol=j.symbol and generation=j.generation and stage='pillar'and result->>'requires_more_data'is distinct from'false');
   update paperlab.deep_companies set audit=p_result,report=jsonb_build_object('generation',j.generation,'completed_at',now(),'coverage',coverage,'full_company_analysis',false,'full_ai_dossier',full_report,'independently_verified',false,'trade_approval',false,'pillars',(select jsonb_agg(jsonb_build_object('pillar',pillar,'result',result))from paperlab.deep_jobs where symbol=j.symbol and generation=j.generation and stage='pillar'and status='completed'),'audit',p_result),last_completed=now(),status=case when full_report then 'full_ai_dossier_completed'else 'dossier_completed_with_gaps'end where symbol=j.symbol;
  end if;
 else
  retry:=case when p_result->>'status'in('rate_limited','provider_unavailable')then paperlab.gemini_retry_time(p_result)else now()+interval'1 hour'end;
  update paperlab.deep_jobs set status=case when p_result->>'status'='blocked_source'or(p_result->>'status'='invalid_response'and attempts>=3)then'blocked'else'retry'end,available_at=retry,result=p_result,token=null,lease_until=null where id=j.id;
 end if;
 if j.model is not null then
  update paperlab.deep_models set retry_after=case when p_result->>'status'in('rate_limited','provider_unavailable')then retry else retry_after end,last_status=p_result->>'status',used=greatest(0,used-case when p_result->>'attempted_calls'='0'then 1 else 0 end)where model=j.model;
 end if;
 insert into paperlab.deep_events(symbol,event,record)values(j.symbol,case when success then j.stage||'_completed'else j.stage||'_saved_for_retry'end,jsonb_build_object('job',j.id,'model',j.model,'status',p_result->>'status','retry_after',retry,'attempts',j.attempts));
 delete from paperlab.deep_events where id in(select id from paperlab.deep_events order by id desc offset 3000);
 update paperlab.deep_runtime set token=null,lease_until=null,job_id=null,status=p_result->>'status',last_success=case when success then now()else last_success end where singleton;
 return true;
end$$;
create or replace function public.paper_deep_read(p_owner uuid,p_symbol text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$begin
 if p_owner is distinct from(select owner_id from paperlab.settings where singleton)then raise exception 'Owner required';end if;
 return jsonb_build_object('runtime',(select to_jsonb(r)-'token'-'lease_until'-'job_id'from paperlab.deep_runtime r),'models',(select jsonb_agg((to_jsonb(b)-'day'-'minute')||jsonb_build_object('used',case when day=(now()at time zone'America/Los_Angeles')::date then used else 0 end))from paperlab.deep_models b),
 'counts',jsonb_build_object('companies',(select count(*)from paperlab.deep_companies),'documents',(select count(*)from paperlab.deep_documents where active),'chunks_total',(select count(*)from paperlab.deep_jobs where stage='extract'and status<>'superseded'),'chunks_completed',(select count(*)from paperlab.deep_jobs where stage='extract'and status='completed'),'reports',(select count(*)from paperlab.deep_companies where report is not null),'full_ai_dossiers',(select count(*)from paperlab.deep_companies where status='full_ai_dossier_completed'),'retrying',(select count(*)from paperlab.deep_jobs where status='retry'),'blocked',(select count(*)from paperlab.deep_jobs where status='blocked')),
 'companies',(select coalesce(jsonb_agg(to_jsonb(c)order by priority desc,symbol),'[]')from(select symbol,priority,coverage,status,last_completed,report,gaps from paperlab.deep_companies where p_symbol is null or symbol=p_symbol order by priority desc,symbol limit 20)c),
 'recent',(select coalesce(jsonb_agg(to_jsonb(e)order by id desc),'[]')from(select *from paperlab.deep_events where p_symbol is null or symbol=p_symbol order by id desc limit 12)e),
 'note','Volledige geladen bronteksten worden in vaste blokken verwerkt en hergebruikt. Zes pijlers en een afzonderlijke eindcontrole volgen daarna. Volledig AI-dossier is geen onafhankelijke audit of koopgoedkeuring. Ontbrekende documenten, brondata en waarderingsaannames blijven zichtbaar. Modelquota vernieuwen om middernacht Pacific; wachtrij hervat automatisch.');
end$$;
do $$begin if to_regprocedure('public.paper_project_read_deep_base_v1(uuid,text)')is null then alter function public.paper_project_read(uuid,text)rename to paper_project_read_deep_base_v1;end if;end$$;
create or replace function public.paper_project_read(p_owner uuid,p_symbol text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$begin return public.paper_project_read_deep_base_v1(p_owner,p_symbol)||jsonb_build_object('deep_research',public.paper_deep_read(p_owner,p_symbol));end$$;
revoke all on function public.paper_deep_seed(uuid,jsonb),public.paper_deep_enable(uuid),public.paper_deep_claim(),public.paper_deep_ingest(uuid,jsonb,jsonb),public.paper_deep_reserve_transfer(uuid,int),public.paper_deep_commit(uuid,jsonb),public.paper_deep_read(uuid,text),public.paper_project_read_deep_base_v1(uuid,text),public.paper_project_read(uuid,text)from public,anon,authenticated,service_role;
grant execute on function public.paper_deep_claim(),public.paper_deep_ingest(uuid,jsonb,jsonb),public.paper_deep_reserve_transfer(uuid,int),public.paper_deep_commit(uuid,jsonb),public.paper_deep_read(uuid,text),public.paper_project_read(uuid,text)to service_role;
commit;
